{
  "declined": "none",
  "criteria": [
    {
      "id": "task",
      "score": 3,
      "reason": "文章有回答題目並表達立場（\"I agree student have part time job\"），但論證較簡單且缺乏具體發展與例子深度。"
    },
    {
      "id": "organization",
      "score": 3,
      "reason": "有明顯段落分段（原因、例子、反面、結論），但段內連接詞使用不穩定，句子間銜接可改進。"
    },
    {
      "id": "vocabulary",
      "score": 2,
      "reason": "使用字彙簡單且多處不正確（例如 \"many thing\", \"many kind of people\"），詞彙變化與精確度不足。"
    },
    {
      "id": "grammar",
      "score": 2,
      "reason": "文法錯誤頻繁（主詞單複數、動詞時態、冠詞、介系詞），句子結構需改善，例如 \"student should have part time job\" 應為複數或加冠詞。"
    }
  ],
  "issues": [
    {
      "quote": "I think student should have part time job.",
      "type": "grammar",
      "why": "主詞與名詞數、冠詞缺失，英語中應使用複數或定冠詞並在複合名詞間加連字或連字符。",
      "suggestion": "I think students should have part-time jobs."
    },
    {
      "quote": "Because they can earn money and learn many thing.",
      "type": "sentence",
      "why": "句子以連接詞開頭造成片語式句子，且單數/複數與不可數名詞錯誤（\"thing\" 應為複數或用不可數表泛稱）。",
      "suggestion": "They can earn money and learn many things."
    },
    {
      "quote": "If student have money they no need ask parents and can buy what they want.",
      "type": "grammar",
      "why": "主詞與動詞配合錯誤（student 應為 students），否定結構與動詞不完整，缺少連接詞或標點使句子難解。",
      "suggestion": "If students have money, they do not need to ask their parents and can buy what they want."
    }
  ],
  "more": [
    {
      "quote": "My cousin work in convenience store, he say he can buy new phone by himself.",
      "type": "verb",
      "why": "動詞時態與主詞配合錯誤（work → works; say → says），並缺少冠詞（a convenience store, a new phone）。",
      "suggestion": "My cousin works in a convenience store; he says he can buy a new phone by himself."
    },
    {
      "quote": "part time job can learn how to talk to people.",
      "type": "grammar",
      "why": "名詞位置錯置，工作不會自己學習，應改為 \"you learn...\" 或使用被動/主動正確表達。",
      "suggestion": "Part-time jobs help you learn how to talk to people."
    },
    {
      "quote": "we only study book, we don't know the society.",
      "type": "word-choice",
      "why": "用詞不自然（\"study book\", \"the society\"），應用更地道表達如 \"only study from books\" 與 \"the real world\"。",
      "suggestion": "we only study from books, so we don't know the real world."
    },
    {
      "quote": "some customer is very rude, so you learn be patient.",
      "type": "article",
      "why": "名詞複數與單複數不一致（customer → customers），並且動詞形式不正確（learn be patient → learn to be patient）。",
      "suggestion": "some customers are very rude, so you learn to be patient."
    },
    {
      "quote": "So student must to control the time.",
      "type": "preposition",
      "why": "動詞片語用法不正確（must 後不加 to），並且名詞數與定冠詞使用需修正（學生複數）。",
      "suggestion": "So students must control their time."
    }
  ],
  "strengths": [
    {
      "quote": "First, money is very important.",
      "why": "能以清楚的主題句開啟段落，表達論點，段落結構基本明確。"
    },
    {
      "quote": "In conclusion, I agree student have part time job but not too many.",
      "why": "有清晰的結論句，表明立場並提醒限制（數量不可過多）。"
    }
  ],
  "summary": "你已經能夠表達同意打工的立場並且分段說明優缺點；接下來請專注於修正主詞與動詞的一致、冠詞與複數形式，還有常用片語（例如 learn to be patient, part-time job(s)）。再加強連接句與詞彙準確性，你的論證會更清楚更自然。"
}
